; Dodge/Plymouth Neon 1995 FCC engine controller (68HC11) - reconstructed source
; Code base: B4CC (Chrysler 5269718 / Mopar Performance 5007033).
; Original firmware (c) 1994 Chrysler Corp. Disassembly annotations derived from
; the work of Robert Lloyd (BoostButton). Generated by tools/gen_source.py -
; edit annotations/*.md and regenerate rather than editing by hand.
;
; Interpolation helpers and RPM rescaling  ($B4A8-$B5FF)

        org     $B4A8


;---------------------------------------------------------------------------------------------------
; InterpSigned  ($B4A8)
;
; Interpolation step for signed cells: A = cell + (difference x fraction / 256). [reviewed]
;
; On entry X points at the first cell, A holds the difference to the next cell and B the fraction
; (0-255). The sign of the difference comes from the preceding compare (N xor V); the product is
; rounded.
;---------------------------------------------------------------------------------------------------
InterpSigned:
        blt     LB4B4
        bra     LB4AE


;---------------------------------------------------------------------------------------------------
; InterpUnsigned  ($B4AC)
;
; Interpolation step for unsigned cells: A = cell + (difference x fraction / 256). [reviewed]
;
; Same as InterpSigned, with the sign of the difference taken from the carry of the preceding
; subtraction.
;---------------------------------------------------------------------------------------------------
InterpUnsigned:
        bcs     LB4B4
LB4AE:
        mul
        adca    #$00
        nega
        bra     LB4B8

LB4B4:
        nega
        mul
        adca    #$00
LB4B8:
        adda    $00,x
        rts


;---------------------------------------------------------------------------------------------------
; RescaleEngineRPM_MM  ($B4BB)
;
; Converts engine RPM to the 3D-table column coordinate RPMRescaledfor3D. [reviewed]
;
; Rounds EngineRpm to 32 rpm per count (EngineRpm_HB plus the carry of the low byte) and passes it
; through the RPMSCL curve. The last routine of code part 1 in B4CC: the 307 bytes after it, up to
; $B5FF, are $FF.
;
; Called from: MainSubLoop
;---------------------------------------------------------------------------------------------------
RescaleEngineRPM_MM:
        ldd     <EngineRpm_HB
        rolb
        clrb
        adca    #$00
        bcs     LB4C9
        ldx     #RPMSCL_RPM3DInputModifierFromRPM    ; RPMSCL: Output is used as the input to the 3D tables
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
LB4C9:
        tba
        staa    <RPMRescaledfor3D
        rts

        dcb.b   307,$FF
